const vendaDaManha = 35;
const vendaDaTarde = 48;
const fornada = 30;

let paes = 120;

paes = paes - vendaDaManha;
console.log('Depois da manhã:', paes);

paes = paes - vendaDaTarde;
console.log('Depois da tarde:', paes);

paes = paes + fornada;
console.log('Depois da fornada:', paes);

