exercises.solution:
const aluno = 'Caio';
const metaDeSeries = 12;
let seriesFeitas = 0;

seriesFeitas = seriesFeitas + 4;
seriesFeitas = seriesFeitas + 5;

console.log(aluno, 'fez', seriesFeitas, 'séries');

const faltam = metaDeSeries - seriesFeitas;
console.log('Faltam', faltam, 'séries');
